const fs = require('node:fs');
const path = require('node:path');

const root = __dirname;
const read = (name) => fs.readFileSync(path.join(root, name), 'utf8');

const engineSource = read('capability-engine.js');
const suggestSource = read('copilot-suggest.js');
const manifestJson = read('custom-elements.json');
const contextJson = read('designer-context.json');
const indexJson = read('component-index.json');
const rulesJson = read('standards-rules.json');
const pluginSource = read('code.src.js');

const preamble = `'use strict';
// Generated by build-plugin-code.cjs — do not edit directly.
${engineSource}
${suggestSource}
const __MODUS_MANIFEST__ = ${manifestJson};
const __MODUS_CONTEXT__ = ${contextJson};
const __MODUS_INDEX__ = ${indexJson};
const __MODUS_RULES__ = ${rulesJson};
const ModusCopilotPlugin = (function () {
`;

const postamble = `
  return { start };
})();
ModusCopilotPlugin.start();
`;

fs.writeFileSync(
  path.join(root, 'code.js'),
  `${preamble}${pluginSource}${postamble}`,
);
console.log('Wrote code.js');
